sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;


    c.search = "";
    c.roundFilter = "";
    c.statusFilter = "";


    // =========================================
    // FILTER
    // =========================================

    c.filterInterview = function(interview) {

        if (!interview) {
            return false;
        }


        // Search
        if (c.search) {

            var searchText =
                c.search.toLowerCase();


            var student =
                (interview.student_name || "")
                .toLowerCase();


            var opportunity =
                (interview.opportunity || "")
                .toLowerCase();


            var application =
                (interview.application_id || "")
                .toLowerCase();


            var round =
                (interview.round || "")
                .toLowerCase();


            var matchesSearch =
                student.indexOf(searchText) >= 0 ||
                opportunity.indexOf(searchText) >= 0 ||
                application.indexOf(searchText) >= 0 ||
                round.indexOf(searchText) >= 0;


            if (!matchesSearch) {
                return false;
            }

        }


        // Round filter
        if (
            c.roundFilter &&
            interview.round != c.roundFilter
        ) {
            return false;
        }


        // Status filter
        if (
            c.statusFilter &&
            interview.status != c.statusFilter
        ) {
            return false;
        }


        return true;

    };


    // =========================================
    // NEW INTERVIEW
    // =========================================
    // Header button = create completely new interview

    c.newInterview = function() {

        $window.location.href =
            "?id=campus360_recruiter_schedule";

    };


    // =========================================
    // SCHEDULE SELECTED CANDIDATE
    // =========================================

    c.scheduleInterview = function(interview) {

        if (!interview || !interview.sys_id) {

            console.log(
                "No interview selected for scheduling"
            );

            return;

        }


        var url =
            "?id=campus360_recruiter_schedule" +
            "&interview_sys_id=" +
            encodeURIComponent(interview.sys_id);


        console.log(
            "Opening schedule page:",
            url
        );


        $window.location.href = url;

    };


    // =========================================
    // VIEW INTERVIEW
    // =========================================

    c.viewInterview = function(interview) {

        if (!interview || !interview.sys_id) {
            return;
        }


        $window.location.href =
            "?id=campus360_recruiter_interview_details" +
            "&sys_id=" +
            encodeURIComponent(interview.sys_id);

    };



    // =========================================
    // REFRESH
    // =========================================

    c.refresh = function() {

        c.server.update();

    };

};

sp_widget.css:
/* =========================================
   MAIN PAGE
   ========================================= */

.interview-page {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto;
    padding: 28px 24px 60px;
    box-sizing: border-box;
    color: #102a56;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
}


/* =========================================
   PAGE HEADER
   ========================================= */

.page-header {
    background: #ffffff;
    border: 1px solid #e1e7f2;
    border-radius: 18px;
    padding: 30px 32px;
    margin-bottom: 24px;
    box-shadow: 0 6px 20px rgba(30, 60, 100, 0.06);
}

.header-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 25px;
}

.section-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.6px;
    color: #5367ee;
    margin-bottom: 7px;
}

.page-header h1 {
    margin: 0;
    font-size: 29px;
    font-weight: 700;
    color: #092a5c;
}

.page-header p {
    margin: 7px 0 0;
    font-size: 14px;
    color: #71809c;
}


/* =========================================
   HEADER BUTTONS
   ========================================= */

.header-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 40px;
    padding: 0 17px;
    border-radius: 9px;
    text-decoration: none !important;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: 0.2s ease;
    box-sizing: border-box;
}

.btn-primary {
    background: #5367ee;
    border: 1px solid #5367ee;
    color: #ffffff !important;
}

.btn-primary:hover {
    background: #4357dc;
    border-color: #4357dc;
}

.btn-secondary {
    background: #ffffff;
    border: 1px solid #cbd5e7;
    color: #40577c !important;
}

.btn-secondary:hover {
    background: #f5f7fb;
}


/* =========================================
   STATISTICS
   ========================================= */

.stats-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}

.stat-card {
    background: #ffffff;
    border: 1px solid #e1e7f2;
    border-radius: 15px;
    padding: 22px;
    min-height: 105px;
    box-sizing: border-box;
    box-shadow: 0 5px 16px rgba(30, 60, 100, 0.045);
}

.stat-label {
    font-size: 12px;
    color: #70809d;
    margin-bottom: 8px;
}

.stat-value {
    font-size: 25px;
    font-weight: 700;
    color: #102a56;
    line-height: 1.2;
}

.stat-description {
    font-size: 11px;
    color: #8a97ad;
    margin-top: 5px;
}


/* =========================================
   FILTER PANEL
   ========================================= */

.filter-panel {
    background: #ffffff;
    border: 1px solid #e1e7f2;
    border-radius: 15px;
    padding: 14px;
    display: grid;
    grid-template-columns: 1fr 190px 190px 44px;
    gap: 10px;
    margin-bottom: 34px;
    box-shadow: 0 5px 16px rgba(30, 60, 100, 0.045);
}

.search-box {
    position: relative;
    display: flex;
    align-items: center;
}

.search-icon {
    position: absolute;
    left: 13px;
    font-size: 13px;
    color: #71809c;
    pointer-events: none;
}

.search-box input {
    width: 100%;
    height: 43px;
    padding: 0 14px 0 36px;
    border: 1px solid #d6deec;
    border-radius: 8px;
    background: #ffffff;
    color: #233d65;
    font-size: 13px;
    outline: none;
    box-sizing: border-box;
}

.search-box input:focus {
    border-color: #5367ee;
    box-shadow: 0 0 0 2px rgba(83, 103, 238, 0.08);
}

.filter-select {
    height: 43px;
    border: 1px solid #d6deec;
    border-radius: 8px;
    padding: 0 12px;
    background: #ffffff;
    color: #263e65;
    font-size: 13px;
    outline: none;
    cursor: pointer;
}

.filter-select:focus {
    border-color: #5367ee;
}

.refresh-btn {
    width: 44px;
    height: 43px;
    border: 1px solid #d6deec;
    border-radius: 8px;
    background: #ffffff;
    color: #5367ee;
    font-size: 20px;
    cursor: pointer;
}

.refresh-btn:hover {
    background: #f3f5ff;
}


/* =========================================
   PIPELINE
   ========================================= */

.pipeline-section {
    width: 100%;
}

.pipeline-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 16px;
}

.pipeline-header h2 {
    margin: 0;
    font-size: 19px;
    font-weight: 600;
    color: #092a5c;
}

.pipeline-header p {
    margin: 5px 0 0;
    color: #71809c;
    font-size: 12px;
}

.candidate-count {
    color: #71809c;
    font-size: 12px;
    font-weight: 500;
}


/* =========================================
   CANDIDATE LIST
   ========================================= */

.candidate-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.candidate-row {
    background: #ffffff;
    border: 1px solid #e1e7f2;
    border-radius: 14px;
    min-height: 90px;
    padding: 16px 18px;
    display: grid;
    grid-template-columns:
        48px
        1.25fr
        0.9fr
        0.9fr
        1fr
        1.25fr
        0.85fr
        auto;
    align-items: center;
    gap: 18px;
    box-sizing: border-box;
    box-shadow: 0 4px 13px rgba(30, 60, 100, 0.04);
    transition: 0.2s ease;
}

.candidate-row:hover {
    border-color: #ccd5ea;
    box-shadow: 0 7px 18px rgba(30, 60, 100, 0.07);
}


/* =========================================
   AVATAR
   ========================================= */

.candidate-avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: #5367ee;
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    font-weight: 700;
}


/* =========================================
   COLUMNS
   ========================================= */

.candidate-column {
    min-width: 0;
}

.column-label {
    font-size: 9px;
    font-weight: 700;
    color: #8995aa;
    margin-bottom: 6px;
    letter-spacing: 0.3px;
}

.column-value {
    color: #122d58;
    font-size: 12px;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.candidate-name {
    color: #122d58;
    font-size: 13px;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.date-column .column-value {
    font-size: 11px;
}


/* =========================================
   STATUS
   ========================================= */

.status-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 25px;
    padding: 0 9px;
    border-radius: 7px;
    font-size: 10px;
    font-weight: 600;
    white-space: nowrap;
    background: #eef2ff;
    color: #5367ee;
}

.status-scheduled {
    background: #eef2ff;
    color: #5367ee;
}

.status-upcoming {
    background: #fff5e5;
    color: #c47b12;
}

.status-completed {
    background: #e9f8f0;
    color: #218452;
}

.status-cancelled {
    background: #fff0f0;
    color: #d34d4d;
}


/* =========================================
   ACTIONS
   ========================================= */

.candidate-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 7px;
}

.action-btn {
    height: 31px;
    padding: 0 11px;
    border-radius: 7px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    transition: 0.2s ease;
}

.schedule-btn {
    background: #5367ee;
    color: #ffffff;
    border: 1px solid #5367ee;
}

.schedule-btn:hover {
    background: #4357dc;
}

.view-btn {
    background: #eef1ff;
    color: #5367ee;
    border: 1px solid #eef1ff;
}

.view-btn:hover {
    background: #e1e6ff;
}


/* =========================================
   EMPTY STATE
   ========================================= */

.empty-state {
    background: #ffffff;
    border: 1px solid #e1e7f2;
    border-radius: 15px;
    min-height: 240px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 35px;
    box-sizing: border-box;
}

.empty-icon {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: #eef1ff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 21px;
    margin-bottom: 15px;
}

.empty-state h3 {
    margin: 0;
    font-size: 17px;
    color: #102a56;
}

.empty-state p {
    margin: 7px 0 18px;
    font-size: 12px;
    color: #7a879d;
}

.empty-action {
    min-width: 170px;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 1100px) {

    .candidate-row {
        grid-template-columns:
            45px
            1.2fr
            0.8fr
            0.9fr
            1fr
            auto;
    }

    .candidate-row .date-column {
        display: none;
    }

    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
    }

}


@media (max-width: 800px) {

    .interview-page {
        padding: 18px 14px 40px;
    }

    .header-content {
        flex-direction: column;
        align-items: flex-start;
    }

    .header-actions {
        width: 100%;
        flex-wrap: wrap;
    }

    .filter-panel {
        grid-template-columns: 1fr;
    }

    .refresh-btn {
        width: 100%;
    }

    .candidate-row {
        grid-template-columns: 45px 1fr auto;
        gap: 12px;
    }

    .candidate-row .candidate-column:not(.candidate-info),
    .candidate-row .status-column {
        display: none;
    }

}


@media (max-width: 520px) {

    .page-header {
        padding: 22px;
    }

    .page-header h1 {
        font-size: 23px;
    }

    .stats-grid {
        grid-template-columns: 1fr;
    }

    .header-actions {
        flex-direction: column;
        align-items: stretch;
    }

    .btn {
        width: 100%;
    }

    .candidate-row {
        grid-template-columns: 40px 1fr;
    }

    .candidate-actions {
        grid-column: 1 / -1;
        justify-content: flex-start;
        padding-top: 8px;
    }

}

sp_widget.script:
(function() {

    data.interviews = [];

    data.counts = {
        scheduled: 0,
        upcoming: 0,
        completed: 0,
        pending: 0
    };


    /*
     * =========================================
     * CURRENT TEST RECRUITER
     * =========================================
     *
     * Temporary company mapping.
     *
     * Ananya Mehta
     * Recruiter ID: RCR001
     * Company: TechNova Solutions
     * Company ID: CMP001
     *
     * Later this will come from
     * the logged-in recruiter.
     */

    data.recruiter_name = 'Ananya Mehta';
    data.recruiter_id = 'RCR001';


    /*
     * =========================================
     * FIND CMP001 COMPANY
     * =========================================
     */

    var companyGR = new GlideRecord(
        'x_snc_campus360_company_master'
    );

    companyGR.addQuery(
        'company_id',
        'CMP001'
    );

    companyGR.setLimit(1);
    companyGR.query();


    var companySysId = '';


    if (companyGR.next()) {

        companySysId =
            companyGR.getUniqueValue();

        data.company_name =
            companyGR.getValue('company_name');

        data.company_id =
            companyGR.getValue('company_id');

    }


    /*
     * =========================================
     * SAFETY CHECK
     * =========================================
     */

    if (!companySysId) {

        data.error =
            'Company CMP001 was not found.';

        return;

    }


    /*
     * =========================================
     * LOAD INTERVIEWS
     * =========================================
     */

    var gr = new GlideRecord(
        'x_snc_campus360_recruiter_interview'
    );


    /*
     * =========================================
     * COMPANY FILTER
     * =========================================
     *
     * Interview
     *      ↓
     * Opportunity
     *      ↓
     * Company
     *
     * Only interviews belonging to
     * CMP001 will be displayed.
     */

    gr.addQuery(
        'opportunity.company',
        companySysId
    );


    gr.orderByDesc('interview_date');

    gr.query();


    var now = new GlideDateTime();


    /*
     * =========================================
     * BUILD INTERVIEW DATA
     * =========================================
     */

    while (gr.next()) {

        var interview = {};


        interview.sys_id =
            gr.getUniqueValue();


        /*
         * Interview ID
         */

        interview.interview_id =
            gr.getValue('interview_id') || '';


        /*
         * Student
         */

        interview.student_name =
            gr.getDisplayValue('student') || '';

        interview.student_sys_id =
            gr.getValue('student') || '';


        /*
         * Application
         */

        interview.application_id =
            gr.getDisplayValue('application') || '';

        interview.application_sys_id =
            gr.getValue('application') || '';


        /*
         * Opportunity
         */

        interview.opportunity =
            gr.getDisplayValue('opportunity') || '';

        interview.opportunity_sys_id =
            gr.getValue('opportunity') || '';


        /*
         * Interview Round
         */

        interview.round =
            gr.getDisplayValue('interview_round') || '';


        /*
         * Interview Mode
         */

        interview.mode =
            gr.getDisplayValue('interview_mode') || '';


        /*
         * Interviewer
         */

        interview.interviewer =
            gr.getValue('interviewer') || '';


        /*
         * Interview Date
         */

        interview.interview_date =
            gr.getDisplayValue('interview_date') || '';


        /*
         * Meeting Link
         */

        interview.meeting_link =
            gr.getValue('meeting_link') || '';


        /*
         * Status
         */

        interview.status =
            gr.getDisplayValue('status') || '';


        /*
         * Result
         */

        interview.result =
            gr.getDisplayValue('result') || '';


        /*
         * Feedback
         */

        interview.feedback =
            gr.getValue('feedback') || '';


        /*
         * Add interview
         */

        data.interviews.push(interview);


        /*
         * =====================================
         * COUNTERS
         * =====================================
         */

        var status =
            (
                gr.getDisplayValue('status') || ''
            ).toLowerCase();


        var result =
            (
                gr.getDisplayValue('result') || ''
            ).toLowerCase();


        /*
         * Scheduled
         */

        if (
            status == 'scheduled' ||
            status.indexOf('schedule') >= 0
        ) {

            data.counts.scheduled++;

        }


        /*
         * Upcoming
         */

        var interviewDate =
            gr.getValue('interview_date');


        if (
            interviewDate &&
            interviewDate > now.getValue() &&
            status.indexOf('cancel') < 0
        ) {

            data.counts.upcoming++;

        }


        /*
         * Completed
         */

        if (
            status == 'completed' ||
            status.indexOf('complete') >= 0
        ) {

            data.counts.completed++;

        }


        /*
         * Pending Result
         */

        if (
            result == '' ||
            result == 'pending'
        ) {

            data.counts.pending++;

        }

    }

})();
